                        "requestId 并发冲突: " + requestId));
        return replay(committed, operation, paramsHash, type);
    }
    T result = action.get();
    try {
        repo.completeRequest(requestId, objectMapper.writeValueAsString(result));
    } catch (Exception e) {
        throw new IllegalStateException("幂等结果序列化失败", e);
    }
    return result;
}

