                "SELECT asset_id, grant_id FROM playout_publication_segment"
                        + " WHERE publication_id = ? AND segment_id = ?",
                publicationId, ctx.p + "seg-1");
        assertThat(main.get("asset_id")).isEqualTo(ctx.movie);
    }

