    putJson("/api/channels/" + ctx.channel + "/drafts/" + DAY,
                    draftBody("req-" + ctx.p + "-gmm", 0, segment(ctx.p + "seg-1", ctx.movie,
                            List.of(companion(ctx.s2, ctx.s1Grant)))))
