    putJson("/api/channels/" + ctx.channel + "/drafts/" + DAY,
                    draftBody("req-" + ctx.p + "-ok", 0, ctx.segmentWithCompanions("seg-1")))
            .andExpect(status().isOk())
            .andExpect(jsonPath("$.version").value(1));
}

